#!/bin/bash
# Owner 2026-11-06 ruling on the silt trap (SILT_TRAP_STYLES_REDRAW_HALF_RES_FLAT): the striped Industrial redraw becomes
# Modern without its tape, and Industrial becomes a raw cement barrier. Both are edits of raw/IndustrialStriped_baffle3q.png,
# so they keep its camera and silhouette. build.py then fits raw/<Look>_baffle3q.png to out/<Look>/RM_SiltTrap.png.
set -u
HERE="$(cd "$(dirname "$0")" && pwd)"; REPO="$(cd "$HERE/../../../../.." && pwd)"
CI="$REPO/skills/generating-images/scripts/codex_image.py"; SRC="$HERE/raw/IndustrialStriped_baffle3q.png"
RMS="$(python3 "$REPO/src/RimMandrake/Utils/rmpaths.py" scratch)" || exit 2
MODERN="Edit image 1, a RimWorld building sprite: a river silt-trap baffle wall. Two changes only. (1) The two bands of yellow-and-black hazard stripes are gone: those top boards are the same plain dark timber as the boards below them, with their grain and bolts. (2) The structure reads as a plain modern structure you would see at a riverbank today: sawn pressure-treated dark brown timber boards and square timber posts with crisp milled edges, the post sleeves and brackets plain galvanized matte grey-steel with ordinary hex bolts; the post tops are plain cut timber with a simple matte grey steel cap. Muted natural colours only. Everything else stays exactly as it is: the same silhouette, the same three-quarter oblique camera, the same number and position of posts and boards, the same position of the object on the canvas, the same canvas size, the same strip of wet brown bank mud at the foot, the same dark wet waterline and small ripples at the posts. The background stays fully transparent (real alpha). Same painterly RimWorld game-art style, no drawn black outline, no cast shadow, no grass."
INDUSTRIAL="Redraw image 1, a RimWorld building sprite of a river silt-trap baffle wall, as an UGLY RAW CAST-CEMENT BARRIER. Image 1 holds the camera, silhouette and composition: the same three-quarter oblique view, the wall running diagonally from upper-left back to lower-right front, the same outline footprint, the same position on the canvas, chunky square posts at the same places with lit tops visible, the wall's top edge showing real thickness, the foot set into the same strip of wet brown bank mud with the same dark wet waterline and small ripples at the posts. Material: everything above the mud is bare unpainted poured concrete: two thick cast-concrete wall panels between blocky square cast-concrete posts with plain flat tops. Dull mottled grey cement with visible horizontal formwork board-marks, cold seams, bug-holes and pitted patches, chipped arrises, dark water stains running down, grimy green-black algae tide-mark along the wet foot, thin rust bleeds running down from a few form-tie holes, a little bent rusty rebar stub at one chipped corner. Utilitarian, stained, heavy, ugly, colourless: the only colours are cement grey, grime and small rust streaks; no paint, no timber, no stripes, no signage. Fully transparent background (real alpha). Same painterly RimWorld game-art style as image 1, no drawn black outline, no cast shadow, no grass. Clean readable shapes that survive shrinking to 128 pixels per cell."
python3 "$CI" edit --model gpt-6.1-sol --out "$HERE/raw/Modern_baffle3q.png" --image "$SRC" --codex-home "$RMS/codex/home_silt1106_modern" --timeout 480 --prompt "$MODERN" > "$HERE/raw/Modern_baffle3q.log" 2>&1; echo "Modern exit=$?"
python3 "$CI" edit --model gpt-6.1-sol --out "$HERE/raw/Industrial_baffle3q.png" --image "$SRC" --codex-home "$RMS/codex/home_silt1106_industrial" --timeout 480 --prompt "$INDUSTRIAL" > "$HERE/raw/Industrial_baffle3q.log" 2>&1; echo "Industrial exit=$?"
